gboolean pango_emoji_iter_next_emoji(PangoEmojiIter *iter) {
  if (!iter || iter->index >= iter->str_len)
    return FALSE;

  if (iter->index >= iter->str_len)
    return FALSE;

  gunichar ch = g_utf8_get_char(iter->str + iter->index);
  g_utf8_next_char(iter->str + iter->index);

  gboolean is_emoji = FALSE;
  gboolean has_zwj = FALSE;
  gboolean has_var_selector = FALSE;

  if (ch == 0x200D)
    has_zwj = TRUE;
  else if (ch == 0xFE0F || ch == 0xFE0E)
    has_var_selector = TRUE;
  else if (is_emoji_base(ch))
    is_emoji = TRUE;

  while (iter->index < iter->str_len) {
    gunichar next_char = g_utf8_get_char(iter->str + iter->index);
    g_utf8_next_char(iter->str + iter->index);

    if (next_char == 0x200D) {
      has_zwj = TRUE;
    } else if (next_char == 0xFE0F || next_char == 0xFE0E) {
      has_var_selector = TRUE;
    } else if (is_emoji_modifier(next_char)) {
      if (!has_zwj && is_emoji_base(ch)) {
        has_zwj = TRUE;
      }
    } else {
      if (is_emoji_base(next_char) || is_emoji_modifier(next_char)) {
        if (!has_zwj && is_emoji_base(ch))
          has_zwj = TRUE;
      } else {
        break;
      }
    }

    if ((has_var_selector || has_zwj || is_emoji_base(next_char) || is_emoji_modifier(next_char)) && !is_emoji)
      is_emoji = TRUE;
  }

  if (is_emoji) {
    iter->is_emoji = TRUE;
    return TRUE;
  } else {
    iter->is_emoji = FALSE;
    return FALSE;
  }
}

gboolean pango_emoji_iter_next_emoji (PangoEmojiIter *iter)
{
  if (iter->pos >= iter->text_len)
    return FALSE;

  gunichar c = g_utf8_get_char (iter->text + iter->pos);
  gint c_len = g_utf8_next_char (iter->text + iter->pos) - (iter->text + iter->pos);

  gboolean is_emoji = FALSE;

  if (pango_is_emoji (c))
    {
      iter->emoji = c;
      iter->start = iter->pos;
      iter->end = iter->pos + c_len;
      iter->is_emoji = TRUE;
      is_emoji = TRUE;
    }

  iter->pos += c_len;

  if (!is_emoji)
    {
      iter->emoji = 0;
      iter->start = 0;
      iter->end = 0;
      iter->is_emoji = FALSE;
    }

  return is_emoji;
}

gboolean pango_emoji_iter_next_emoji (PangoEmojiIter *iter)
{
  gunichar ch;
  int i;
  gboolean found;

  if (iter->pos >= iter->text_len)
    return FALSE;

  found = FALSE;

  for (i = iter->pos; i < iter->text_len; i++)
    {
      ch = g_utf8_get_char (iter->text + i);
      int char_len = g_utf8_next_char (iter->text + i) - (iter->text + i);

      if (ch == 0x200D) /* Zero-Width Joiner */
        {
          iter->is_emoji = TRUE;
          iter->start = i;
          iter->end = i + char_len;
          iter->pos = i + char_len;
          return TRUE;
        }
      else if (ch == 0xFE0F || ch == 0xFE0E) /* Variation Selector */
        {
          if (iter->is_emoji)
            {
              iter->end = i + char_len;
              iter->pos = i + char_len;
              return TRUE;
            }
        }
      else if (is_emoji (ch))
        {
          iter->is_emoji = TRUE;
          iter->start = i;
          iter->end = i + char_len;
          iter->pos = i + char_len;
          return TRUE;
        }
      else
        {
          if (iter->is_emoji)
            {
              iter->end = i;
              iter->pos = i;
              return TRUE;
            }
          iter->is_emoji = FALSE;
          iter->pos = i + char_len;
        }
    }

  if (found)
    {
      iter->end = iter->text_len;
      return TRUE;
    }

  iter->pos = iter->text_len;
  return FALSE;
}

gboolean pango_emoji_iter_next_emoji (PangoEmojiIter *iter)
{
  gunichar ch;
  gboolean is_emoji;
  gint i;

  if (iter->index >= iter->text_len)
    return FALSE;

  is_emoji = FALSE;
  iter->emoji_type = PANGO_EMOJI_NONE;

  for (i = iter->index; i < iter->text_len; i++)
    {
      ch = iter->text[i];

      if (g_unichar_is_emoji (ch))
        {
          iter->emoji_type = PANGO_EMOJI_SINGLE;
          iter->start = i;
          iter->end = i + 1;
          is_emoji = TRUE;
          break;
        }
      else if (g_unichar_is_emoji_base (ch))
        {
          iter->emoji_type = PANGO_EMOJI_SEQUENCE;
          iter->start = i;
          iter->end = i + 1;
          is_emoji = TRUE;
          break;
        }
      else if (ch == 0x200D) /* Zero-width joiner */
        {
          if (i + 1 < iter->text_len && g_unichar_is_emoji_modifier (iter->text[i + 1]))
            {
              iter->emoji_type = PANGO_EMOJI_SEQUENCE;
              iter->start = i;
              iter->end = i + 2;
              is_emoji = TRUE;
              break;
            }
        }
      else if (ch == 0xFE0F || ch == 0xFE0E) /* Variation selector */
        {
          if (i > 0 && g_unichar_is_emoji (iter->text[i - 1]))
            {
              iter->end = i + 1;
              is_emoji = TRUE;
              break;
            }
        }
    }

  if (is_emoji)
    {
      iter->index = iter->end;
      return TRUE;
    }
  else
    {
      iter->index = iter->text_len;
      return FALSE;
    }
}

gboolean pango_emoji_iter_next_emoji(PangoEmojiIter *iter) {
  if (iter->index >= iter->str_end)
    return FALSE;

  iter->emoji_type = PANGO_EMOJI_NONE;
  gunichar c = g_utf8_get_char(iter->str);
  gint len = g_utf8_get_char_length(*iter->str);

  if (c == 0x200D && iter->emoji_type == PANGO_EMOJI_BASE) {
    iter->emoji_type = PANGO_EMOJI_ZWJ_SEQUENCE;
  } else if (c == 0xFE0F && iter->emoji_type == PANGO_EMOJI_EMOJI) {
    iter->emoji_type = PANGO_EMOJI_EMOJI_PRESENTATION;
  } else if (c == 0xFE0E && iter->emoji_type == PANGO_EMOJI_EMOJI) {
    iter->emoji_type = PANGO_EMOJI_EMOJI_TEXT;
  } else {
    iter->emoji_type = pango_is_emoji(c) ? PANGO_EMOJI_EMOJI : PANGO_EMOJI_NONE;
  }

  iter->str += len;
  iter->index += len;

  if (iter->emoji_type != PANGO_EMOJI_NONE) {
    iter->start = iter->index - len;
    iter->end = iter->index;
    return TRUE;
  }

  return FALSE;
}
